'use client';

import { FormEvent, useEffect, useRef, useState } from 'react';
import Image from 'next/image';

const sizeOptions = [100, 200, 300, 400, 500, 600, 700];

export default function HomePage() {
  const [url, setUrl] = useState('');
  const [size, setSize] = useState('300');
  const [showSpinner, setShowSpinner] = useState(false);
  const [qrValue, setQrValue] = useState('');
  const qrRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!qrValue || !qrRef.current) return;

    let cancelled = false;

    const render = async () => {
      const { default: QrCreator } = await import('qr-creator');
      if (cancelled || !qrRef.current) return;
      qrRef.current.innerHTML = '';
      QrCreator.render(
        {
          text: qrValue,
          size: Number(size),
          ecLevel: 'M',
          fill: '#000000',
          background: '#ffffff',
          radius: 0.0,
        },
        qrRef.current
      );
    };

    render();
    return () => { cancelled = true; };
  }, [qrValue, size]);

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (!url.trim()) {
      alert('Please enter a URL');
      return;
    }

    setQrValue('');
    setShowSpinner(true);

    setTimeout(() => {
      setShowSpinner(false);
      setQrValue(url);
    }, 1000);
  };

  const handleDownload = () => {
    if (!qrRef.current) return;
    const canvas = qrRef.current.querySelector('canvas');
    if (!canvas) return;

    const link = document.createElement('a');
    link.download = 'qrcode.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const handleCopy = async () => {
    if (!qrRef.current) return;
    const canvas = qrRef.current.querySelector('canvas');
    if (!canvas) return;

    try {
      const blob = await new Promise<Blob>((resolve) =>
        canvas.toBlob((b) => resolve(b!), 'image/png')
      );
      await navigator.clipboard.write([
        new ClipboardItem({ 'image/png': blob }),
      ]);
    } catch {
      alert('Failed to copy. Try downloading instead.');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-slate-100">
      {/* Header */}
      <header className="sticky top-0 z-50 backdrop-blur-md bg-white/80 border-b border-slate-200/60">
        <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-violet-500/25">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
              </svg>
            </div>
            <span className="text-lg font-bold text-slate-800">QR Generator</span>
          </div>
          <a
            href="https://github.com"
            target="_blank"
            rel="noopener noreferrer"
            className="text-sm text-slate-500 hover:text-slate-800 transition-colors"
          >
            Free &amp; Open Source
          </a>
        </div>
      </header>

      {/* Hero */}
      <section className="relative overflow-hidden">
        {/* Background decoration */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute -top-40 -right-40 w-80 h-80 bg-violet-200/40 rounded-full blur-3xl" />
          <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-indigo-200/40 rounded-full blur-3xl" />
        </div>

        <div className="relative max-w-6xl mx-auto px-6 pt-16 pb-20 md:pt-24 md:pb-28">
          <div className="text-center max-w-2xl mx-auto mb-14">
            <div className="inline-flex items-center gap-2 bg-violet-100 text-violet-700 text-sm font-medium px-4 py-1.5 rounded-full mb-6">
              <span className="w-2 h-2 bg-violet-500 rounded-full animate-pulse" />
              100% Free — No Sign-up Required
            </div>
            <h1 className="text-4xl md:text-6xl font-bold text-slate-900 leading-tight tracking-tight mb-5">
              Create QR Codes
              <span className="bg-gradient-to-r from-violet-600 to-indigo-600 bg-clip-text text-transparent"> Instantly</span>
            </h1>
            <p className="text-lg text-slate-500 leading-relaxed">
              Generate high-quality QR codes for any URL in seconds. Download as PNG or copy straight to your clipboard.
            </p>
          </div>

          {/* Main Card */}
          <div className="max-w-4xl mx-auto">
            <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-200/60 overflow-hidden">
              <div className="grid md:grid-cols-5">
                {/* Form Side */}
                <div className="md:col-span-3 p-8 md:p-10">
                  <form id="generate-form" onSubmit={handleSubmit}>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">
                      Website URL
                    </label>
                    <input
                      id="url"
                      type="url"
                      placeholder="https://example.com"
                      className="w-full border border-slate-200 rounded-xl px-4 py-3 text-slate-700 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-violet-500/40 focus:border-violet-400 transition-all mb-5"
                      required
                      value={url}
                      onChange={(e) => setUrl(e.target.value)}
                    />

                    <label className="block text-sm font-semibold text-slate-700 mb-2">
                      QR Code Size
                    </label>
                    <select
                      className="w-full border border-slate-200 rounded-xl px-4 py-3 text-slate-700 focus:outline-none focus:ring-2 focus:ring-violet-500/40 focus:border-violet-400 transition-all mb-6"
                      name="size"
                      id="size"
                      value={size}
                      onChange={(e) => setSize(e.target.value)}
                    >
                      {sizeOptions.map((option) => (
                        <option key={option} value={String(option)}>
                          {option} × {option} px
                        </option>
                      ))}
                    </select>

                    <button
                      className="w-full bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-700 hover:to-indigo-700 text-white font-semibold py-3.5 px-6 rounded-xl shadow-lg shadow-violet-500/25 hover:shadow-violet-500/40 transition-all duration-200 cursor-pointer active:scale-[0.98]"
                      type="submit"
                    >
                      Generate QR Code
                    </button>
                  </form>
                </div>

                {/* QR Preview Side */}
                <div className="md:col-span-2 bg-slate-50/80 border-t md:border-t-0 md:border-l border-slate-200/60 p-8 flex flex-col items-center justify-center min-h-[280px]">
                  {showSpinner && (
                    <div role="status" className="flex flex-col items-center gap-3">
                      <div className="w-10 h-10 border-4 border-slate-200 border-t-violet-500 rounded-full animate-spin" />
                      <span className="text-sm text-slate-400">Generating...</span>
                    </div>
                  )}

                  {!showSpinner && qrValue && (
                    <div className="flex flex-col items-center gap-4 animate-fadeIn">
                      <div
                        ref={qrRef}
                        className="rounded-xl overflow-hidden shadow-lg shadow-slate-200"
                      />
                      <div className="flex gap-2 w-full">
                        <button
                          onClick={handleDownload}
                          className="flex-1 bg-gradient-to-r from-rose-500 to-pink-500 hover:from-rose-600 hover:to-pink-600 text-white text-sm font-semibold py-2.5 px-3 rounded-lg shadow-md shadow-rose-500/20 transition-all duration-200 cursor-pointer active:scale-[0.97]"
                        >
                          ↓ Save
                        </button>
                        <button
                          onClick={handleCopy}
                          className="flex-1 bg-slate-700 hover:bg-slate-800 text-white text-sm font-semibold py-2.5 px-3 rounded-lg shadow-md transition-all duration-200 cursor-pointer active:scale-[0.97]"
                        >
                          Copy
                        </button>
                      </div>
                    </div>
                  )}

                  {!showSpinner && !qrValue && (
                    <div className="flex flex-col items-center gap-3 text-center">
                      <Image
                        className="w-24 opacity-30"
                        src="/img/qr-code.svg"
                        alt=""
                        width={96}
                        height={96}
                      />
                      <span className="text-sm text-slate-400">
                        Your QR code will appear here
                      </span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Features */}
      <section className="max-w-6xl mx-auto px-6 pb-20">
        <div className="grid md:grid-cols-3 gap-6">
          {[
            {
              icon: (
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 13.5l10.5-11.25L12 10.5h8.25L9.75 21.75 12 13.5H3.75z" />
                </svg>
              ),
              title: 'Lightning Fast',
              desc: 'QR codes generated instantly in your browser — no server needed.',
            },
            {
              icon: (
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z" />
                </svg>
              ),
              title: '100% Private',
              desc: 'Everything happens locally. No data leaves your browser.',
            },
            {
              icon: (
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M16.5 12L12 16.5m0 0L7.5 12m4.5 4.5V3" />
                </svg>
              ),
              title: 'Download or Copy',
              desc: 'Save as PNG image or copy directly to your clipboard.',
            },
          ].map((feature) => (
            <div
              key={feature.title}
              className="bg-white rounded-2xl border border-slate-200/60 p-6 hover:shadow-lg hover:shadow-slate-200/50 transition-all duration-300 hover:-translate-y-0.5"
            >
              <div className="w-11 h-11 bg-gradient-to-br from-violet-100 to-indigo-100 text-violet-600 rounded-xl flex items-center justify-center mb-4">
                {feature.icon}
              </div>
              <h3 className="text-lg font-bold text-slate-800 mb-2">{feature.title}</h3>
              <p className="text-sm text-slate-500 leading-relaxed">{feature.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Footer */}
      <footer className="border-t border-slate-200/60 bg-white/50 backdrop-blur-sm">
        <div className="max-w-6xl mx-auto px-6 py-8 flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-2 text-sm text-slate-400">
            <div className="w-5 h-5 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-md flex items-center justify-center">
              <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
              </svg>
            </div>
            QR Code Generator
          </div>
          <p className="text-xs text-slate-400">
            Free to use. No tracking. No ads.
          </p>
        </div>
      </footer>
    </div>
  );
}
